const clone=structuredClone;
export const EFFORT={export:[2,8,1.25,1],invoice:[2,9,1,1],audit:[3,7,1.25,1],access:[2,6,1,1],label:[1,6,.5,.5],bundle:[3,9,1.5,1.5],partner:[2.5,7,1.25,1],branding:[1.5,6,.5,.5]};
export function capacityDefaults(){return {budgets:[12,12,12,12,12,12],aging:.15,pair:.5,effort:Object.fromEntries(Object.entries(EFFORT).map(([id,[setup,standard,maintenance,retire]])=>[id,{setup,standard,maintenance,retire}])),jobs:[{id:'onboard',title:'Simplify onboarding',arrive:0,effort:10},{id:'diagnose',title:'Build troubleshooting tools',arrive:1,effort:8},{id:'release',title:'Automate release checks',arrive:2,effort:9},{id:'selfserve',title:'Make settings self-service',arrive:3,effort:8},{id:'quality',title:'Show data quality',arrive:4,effort:10},{id:'upgrade',title:'Improve the upgrade guide',arrive:5,effort:6}]};}
export function validateCapacity(c){if(!c||!Array.isArray(c.budgets)||c.budgets.length!==6)throw Error('Six capacity budgets are required.');const num=(v,min,max)=>{if(!Number.isFinite(v)||v<min||v>max)throw Error('Invalid effort assumption.');};c.budgets.forEach(v=>num(v,0,100));num(c.aging,0,3);num(c.pair,0,6);for(const id of Object.keys(EFFORT))for(const key of ['setup','standard','maintenance','retire'])num(c.effort?.[id]?.[key],0,50);if(!Array.isArray(c.jobs)||c.jobs.length>12)throw Error('Keep at most twelve core work items.');const ids=new Set();for(const j of c.jobs){if(typeof j.id!=='string'||!j.id||ids.has(j.id)||typeof j.title!=='string'||!j.title.trim()||j.title.length>300||!Number.isInteger(j.arrive)||j.arrive<0||j.arrive>5)throw Error('Invalid core work item.');ids.add(j.id);num(j.effort,.5,100);}return c;}
export function capacityPreview(s,totals,requests){const c=validateCapacity(s.capacity),on=s.entries.filter(e=>['tailored','standard'].includes(e.plan)),items=[];let setup=0,maintenance=0,retirement=0;
 for(const entry of s.entries){const r=requests.find(r=>r.id===entry.id),x=c.effort[entry.id],was=['tailored','standard'].includes(entry.status),now=['tailored','standard'].includes(entry.plan),age=entry.since===null?0:s.quarter-entry.since;let change=0,upkeep=0,exit=0;
 if(now){upkeep=entry.plan==='standard'?x.maintenance*.4:x.maintenance+age*c.aging;if(!was&&entry.plan==='tailored'){const reuse=on.some(o=>o.id!==entry.id&&o.plan==='standard'&&requests.find(r=>r.id===o.id).touches.some(t=>r.touches.includes(t)));change=Math.max(0,x.setup-(reuse?1.5:0));}if(entry.plan==='standard'&&entry.status!=='standard')change=x.standard;}
 if(was&&entry.plan==='retired')exit=x.retire;setup+=change;maintenance+=upkeep;retirement+=exit;items.push({id:entry.id,setup:change,maintenance:upkeep,retirement:exit});}
 const pairs=totals.pairs.map(p=>{const standard=on.some(e=>(e.id===p.a||e.id===p.b)&&e.plan==='standard');const effort=c.pair*(standard?1/3:1);maintenance+=effort;return {...p,effort};});
 const budget=c.budgets[s.quarter],required=setup+maintenance+retirement,feasible=required<=budget+1e-9;let left=Math.max(0,budget-required);
 // Core work is divisible and queued by arrival, then list order. Changes
 // settle as whole-quarter choices, so infeasible plans earn no new outcomes.
 const work=c.jobs.map((j,index)=>({...j,index})).filter(j=>j.arrive<=s.quarter).sort((a,b)=>a.arrive-b.arrive||a.index-b.index).map(j=>{const previous=s.history.reduce((n,h)=>n+(h.capacity?.work.find(w=>w.id===j.id)?.delivered||0),0),remainingBefore=Math.max(0,j.effort-previous),delivered=feasible?Math.min(left,remainingBefore):0;left-=delivered;return {id:j.id,title:j.title,effort:j.effort,remainingBefore,delivered,remainingAfter:Math.max(0,remainingBefore-delivered)};});
 const waitingBefore=work.reduce((n,j)=>n+j.remainingBefore,0),coreDone=work.reduce((n,j)=>n+j.delivered,0),coreRemaining=work.reduce((n,j)=>n+j.remainingAfter,0);
 return {budget,required,setup,maintenance,retirement,items,pairs,feasible,shortfall:Math.max(0,required-budget),coreDone,coreRemaining,spare:feasible?left:0,work,maintenanceDisplaced:feasible?Math.min(waitingBefore,Math.max(0,budget-setup-retirement))-coreDone:null,allDisplaced:feasible?Math.min(waitingBefore,budget)-coreDone:null};}
export function configureCapacity(s,patch){if(!s.capacity)throw Error('Replay with capacity to use effort assumptions.');if(s.quarter)throw Error('Effort and work assumptions are fixed after the first settlement.');const next=clone(s);next.capacity={...next.capacity,...clone(patch)};validateCapacity(next.capacity);return next;}
export function setBudget(s,quarter,value){if(!s.capacity||!Number.isInteger(quarter)||quarter<s.quarter||quarter>5||!Number.isFinite(value)||value<0||value>100)throw Error('Change an unsettled quarter’s budget, between 0 and 100.');const next=clone(s);next.capacity.budgets[quarter]=value;return next;}
